async function dispatchBusyFollowup(j,activity){
 const current=effectiveThreads().map(t=>t.id===j.threadId?{...t,activity}:t);
 await sendQueuedNow(state,j,current,{desktopControl,bridge,media});
 if(j.executionDispatched)return;
 if(j.threadId)throw Error('The agent became busy before dispatch. Nothing was sent; retry Send now.');
 await startJob(j);
}
